svg.script:
const svg = document.documentElement;
const full = svg.viewBox.baseVal;
const W = full.width, H = full.height;
let x = W/2, y = H/2, scale, drag;
function fitScale() { return Math.min(innerWidth/W,innerHeight/H); }
function paint() {
  scale = Math.max(fitScale(),Math.min(4,scale));
  const w = innerWidth/scale, h = innerHeight/scale;
  x = w >= W ? W/2 : Math.max(w/2,Math.min(W-w/2,x));
  y = h >= H ? H/2 : Math.max(h/2,Math.min(H-h/2,y));
  svg.setAttribute('viewBox',[x-w/2,y-h/2,w,h].join(' '));
}
function detail() { scale = Math.min(innerWidth/1350,innerHeight/1800); paint(); }
function zoom(by,px=innerWidth/2,py=innerHeight/2) {
  const prev = scale;
  scale = Math.max(fitScale(),Math.min(4,prev*by));
  x += (px-innerWidth/2)*(1/prev-1/scale);
  y += (py-innerHeight/2)*(1/prev-1/scale);
  paint();
}
svg.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-Math.sign(e.deltaY)*.25),e.clientX,e.clientY);},{passive:false});
svg.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];svg.setPointerCapture(e.pointerId);});
svg.addEventListener('pointermove',e=>{if(!drag)return;x+=(drag[0]-e.clientX)/scale;y+=(drag[1]-e.clientY)/scale;drag=[e.clientX,e.clientY];paint();});
svg.addEventListener('lostpointercapture',()=>drag=null);
window.addEventListener('keydown',e=>{if(e.key==='Home'){e.preventDefault();scale=fitScale();paint();} if(e.key==='0')detail(); if(e.key==='+'||e.key==='=')zoom(1.5); if(e.key==='-')zoom(1/1.5);});
svg.addEventListener('dblclick',()=>{if(scale<=fitScale()*1.01)detail();else{scale=fitScale();paint();}});
window.addEventListener('resize',paint);
detail();
